-- ============================================================
-- 帮助中心：将「系统操作手册与规范」写入知识库（幂等 upsert）
-- 目的：让 AI 问答(RAG 检索)能检索到这份规范，用户也能在「帮助中心」看到同样内容
-- 执行：在 kb 库执行本文件（MySQL 8）
-- 说明：content 为 PUBLISHED 文档，RagService 检索仅取 PUBLISHED，故 AI 可命中
--       幂等：已存在同名标题则更新内容；不存在则插入（可反复执行，始终是最新版）
-- ============================================================

SET @hc_title = '知识库系统操作手册与规范';
SET @hc_content = '<h2>知识库系统操作手册与规范</h2><h3>快速开始</h3><p>嗨，欢迎来到知识库 👋 第一次来？先登录就好：</p><ul><li>点右上角「登录」，输入账号密码，滑一下<strong>滑动验证码</strong>就能进来啦。</li><li>还没账号？点「注册」就能开一个；密码忘了也不怕，登录页有「修改密码」。</li></ul><p>登录后你就到了知识库首页，这儿能看到「最新」「最热」的文章，顶部搜索框还能搜全站内容。</p><h3>写文章与发布</h3><ul><li>左侧菜单「写文章」进入富文本编辑器（支持标题、加粗、列表、图片、表格、代码块等）。</li><li>填写<strong>标题</strong>，选择<strong>分类</strong>与<strong>标签</strong>，便于他人检索。</li><li>点击「提交」进入<strong>待审核</strong>状态，管理员审核通过后公开；也可「保存草稿」稍后继续。</li><li>「我的帖子」可查看自己文章的状态（已发布 / 待审核 / 草稿 / 已封禁）。</li></ul><h3>阅读与互动</h3><ul><li><strong>搜索</strong>：顶部搜索框或「搜索结果」页，按关键词检索文章标题与正文。</li><li><strong>收藏 / 点赞 / 评论</strong>：在文章详情页操作；收藏的文章见于「我的收藏」。</li><li><strong>浏览历史</strong>：自动记录你读过的文章，见于「浏览历史」。</li><li>文章内「小窗阅读」可在悬浮窗中阅读，不影响继续浏览其他页面。</li></ul><h3>AI 智能问答</h3><p>有啥想问的，来「AI 问答」跟我聊～</p><ul><li>两种模式：<strong>知识库</strong>（我会先在本站已发布的文档里找答案，还会给你标出来源，点一下就能看原文）；<strong>通用</strong>（就是跟大模型闲聊、聊啥都行）。</li><li>你可以开好几个对话，还能设置「对话条例」和「个人习惯」，让我更懂你的口味。</li><li>小提醒：每小时每位用户最多问 20 次哦。</li><li>要是看到「AI 问答暂不可用」，那是管理员还没把 AI 服务打开（需要配置智谱 API Key），找管理员帮帮忙就好。</li></ul><h3>共享文档协作</h3><p>想跟同事一起写文档？进「共享文档」建个团队空间就好啦。</p><ul><li>新建的空间默认给你 <strong>2GB</strong> 容量，够日常用了。</li><li>容量不够了？在空间里点「申请扩容」，填好想要的容量和理由，交给管理员审批通过就生效～ 创建之后容量只能由管理员帮你调，自己改不了哦。</li><li>空间里支持<strong>多人实时一起编辑</strong>（用的是 CRDT 技术，你能看到别人正停在哪儿、敲了啥）。</li><li>在空间里你会被赋予不同的操作权限：有的能只看、有的能一起改、有的能帮忙管理——具体能做什么，空间主人会帮你安排好，你按提示操作就行，不用记那些角色名。</li></ul><h3>培训与学习</h3><ul><li>进入「培训」浏览课程；点开课程查看章节列表。</li><li>每章为<strong>独立学习页</strong>，支持正文阅读与<strong>章节笔记</strong>（自动保存）。</li><li>学完点击「标记完成」，进度自动累积。</li></ul><h3>考试与答题</h3><ul><li>「在线考试」：参加测评、提交后查看成绩与解析。</li><li>「答题」：闯关模式，趣味答题积累积分。</li></ul><h3>积分体系</h3><ul><li>发帖、评论、获得点赞等行为可累积<strong>积分</strong>。</li><li>「积分排行榜」查看全站排名，激励优质内容创作。</li></ul><h3>个人中心</h3><ul><li>「个人资料」：修改头像、简介、登录密码。</li><li>「我的收藏」「浏览历史」「通知」：管理你的内容与消息。</li></ul><h3>使用规范与社区公约</h3><ul><li>发布内容须<strong>合法合规</strong>，禁止传播违法违规、谣言、色情、暴力等信息。</li><li>尊重<strong>知识产权</strong>，转载请注明出处，勿上传侵权内容。</li><li>文明互动：禁止人身攻击、刷屏、发布垃圾广告。</li><li>账号安全：妥善保管密码，不共享账号；发现异常及时修改密码或联系管理员。</li></ul>';

INSERT INTO kb_document (title, content, category, tags, owner_id, status, views, hot, pinned, likes, created_at, updated_at)
SELECT @hc_title, @hc_content, '帮助中心', '帮助,操作手册,规范',
       (SELECT id FROM kb_user WHERE username = 'admin' LIMIT 1),
       'PUBLISHED', 0, 0, 0, 0, NOW(), NOW()
FROM dual
WHERE NOT EXISTS (SELECT 1 FROM kb_document WHERE title = @hc_title);

UPDATE kb_document
SET content = @hc_content,
    category = '帮助中心',
    tags = '帮助,操作手册,规范',
    updated_at = NOW()
WHERE title = @hc_title;
